#!/bin/sh
D="$(cd "$(dirname "$0")/.." && pwd)"
case "$1 $2" in
"auth status") if [ -f "$D/fixtures/unauth" ]; then echo "You are not logged in to any hosts. Run gh auth login" >&2; exit 1; fi; exit 0;;
"repo view") echo "local/work-repo true";;
"label list") cat "$D/fixtures/labels.json";;
"issue list") echo "issue list $*" >> "$D/gh.log"; cat "$D/fixtures/issues.json";;
"issue create") { echo "--- issue create"; for a in "$@"; do printf "ARG: %s
" "$a"; done; } >> "$D/gh.log"; prev=; for a in "$@"; do if [ "$prev" = --body-file ]; then { echo "BODY<<"; cat "$a"; echo ">>BODY"; } >> "$D/gh.log"; fi; prev="$a"; done; echo "https://issues.invalid/1";;
*) echo "unsupported: $*" >> "$D/gh.log"; exit 1;;
esac
STUB
chmod +x /tmp/eval-new-issue-0/bin/gh && printf '%s' '[{"name":"bug","description":"Something is broken"},{"name":"enhancement","description":"New feature or request"},{"name":"documentation","description":"Docs changes"},{"name":"installer","description":"Installer CLI"}]' > /tmp/eval-new-issue-0/fixtures/labels.json && printf '%s' '[]' > /tmp/eval-new-issue-0/fixtures/issues.json && : > /tmp/eval-new-issue-0/gh.log && export PATH=/tmp/eval-new-issue-0/bin:$PATH

